// An EXPRESSIVE sign-in surface on the restrained kit. Governing skill: godxjp-ui-brand-surface
// (skills/godxjp-ui-brand-surface/SKILL.md, also `get_consumer_skill`). Its CSS is ONE file scoped
// to .brand-surface: skills/godxjp-ui-brand-surface/references/exemplar-css.md.
//
// Expressive outside, kit inside: every control is a kit component; the picture is a stage behind
// and beside them. No hex, no utility class, no hand-rolled surface in this file, so
// `npx @godxjp/ui audit` stays at zero; the look lives in the CSS file.
//
// The picture shows THE PRODUCT ITSELF (here: the units it manages, the routes between them and
// work moving along the routes), drawn as SVG from fixed numbers: the same picture on every load,
// no image, no WebGL, no network. Replace NODES and LINKS with your product's own objects.
//
// Consumer dependencies, pinned in your package.json: gsap, @gsap/react, lucide-react.
// Wrap it: every shared auth page (sign-in, second factor, reset, invitation) passes its form as
// children, so they change together.
import { useGSAP } from "@gsap/react";
import { gsap } from "gsap";
import { Pause, Play } from "lucide-react";
import { type ReactNode, useRef, useState } from "react";
import { ThemeScope } from "@godxjp/ui/app";
import { Alert, AlertDescription } from "@godxjp/ui/feedback";
import { Button, Heading, Text } from "@godxjp/ui/general";
import { Flex } from "@godxjp/ui/layout";
import { AppSettingPicker } from "@godxjp/ui/navigation";

gsap.registerPlugin(useGSAP);

type Point = { x: number; y: number };
type MapNode = Point & { id: string; kind: "unit" | "actor" };

/** A metro-map route: straight along the longer axis, then 45 degrees into the target. */
function route(a: Point, b: Point): { d: string; length: number } {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const ax = Math.abs(dx);
  const ay = Math.abs(dy);
  const bend =
    ax >= ay ? { x: b.x - Math.sign(dx) * ay, y: a.y } : { x: a.x, y: b.y - Math.sign(dy) * ax };
  const length = Math.hypot(bend.x - a.x, bend.y - a.y) + Math.hypot(b.x - bend.x, b.y - bend.y);
  return { d: `M${a.x} ${a.y}L${bend.x} ${bend.y}L${b.x} ${b.y}`, length: Math.round(length) };
}

// PLACEHOLDER topology: replace with what your product manages. Labels are decoration
// (the SVG is aria-hidden), so they carry nothing the page needs.
const NODES: MapNode[] = [
  { id: "gateway", x: 120, y: 180, kind: "unit" },
  { id: "secrets", x: 300, y: 120, kind: "unit" },
  { id: "build-01", x: 480, y: 240, kind: "unit" },
  { id: "build-02", x: 620, y: 120, kind: "unit" },
  { id: "worker·a", x: 180, y: 360, kind: "actor" },
  { id: "node-03", x: 420, y: 420, kind: "unit" },
  { id: "node-04", x: 620, y: 420, kind: "unit" },
  { id: "desk-17", x: 100, y: 560, kind: "unit" },
  { id: "worker·b", x: 300, y: 620, kind: "actor" },
  { id: "db-main", x: 540, y: 620, kind: "unit" },
  { id: "edge-02", x: 640, y: 780, kind: "unit" },
  { id: "files", x: 200, y: 800, kind: "unit" },
  { id: "worker·c", x: 420, y: 800, kind: "actor" },
];
const LINKS: [string, string][] = [
  ["gateway", "secrets"], ["secrets", "build-02"], ["secrets", "build-01"], ["build-01", "build-02"],
  ["gateway", "worker·a"], ["worker·a", "node-03"], ["build-01", "node-03"], ["node-03", "node-04"],
  ["build-02", "node-04"], ["worker·a", "desk-17"], ["desk-17", "worker·b"], ["node-03", "worker·b"],
  ["worker·b", "db-main"], ["node-04", "db-main"], ["db-main", "edge-02"], ["worker·b", "files"],
  ["files", "worker·c"], ["worker·c", "db-main"], ["worker·c", "edge-02"],
];
const at = (id: string) => NODES.find((n) => n.id === id) as MapNode;
const ROUTES = LINKS.map(([a, b]) => route(at(a), at(b)));

function ProductMap() {
  return (
    <svg className="brand-surface-art" viewBox="0 0 720 900" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
      <defs>
        <pattern id="brand-surface-grid" width="20" height="20" patternUnits="userSpaceOnUse">
          <circle cx="1" cy="1" r="1" className="brand-surface-dot" />
        </pattern>
      </defs>
      <rect className="brand-surface-grid" width="720" height="900" fill="url(#brand-surface-grid)" />
      <g>
        {ROUTES.map((r, i) => (
          <path key={i} className="brand-surface-route" d={r.d} strokeDasharray={r.length} strokeDashoffset={0} data-length={r.length} />
        ))}
      </g>
      <g className="brand-surface-packets">
        {ROUTES.map((r, i) => (
          <path key={i} className="brand-surface-packet" d={r.d} strokeDasharray={`18 ${r.length + 18}`} strokeDashoffset={18} data-length={r.length} />
        ))}
      </g>
      <g>
        {NODES.map((n) =>
          n.kind === "unit" ? (
            <g key={n.id} className="brand-surface-node" transform={`translate(${n.x} ${n.y})`}>
              <rect x="-17" y="-11" width="34" height="22" rx="4" className="brand-surface-box" />
              <circle cx="-8" cy="0" r="2.2" className="brand-surface-led" />
              <text x="24" y="4" className="brand-surface-label">{n.id}</text>
            </g>
          ) : (
            <g key={n.id} className="brand-surface-node brand-surface-actor" transform={`translate(${n.x} ${n.y})`}>
              <circle r="11" className="brand-surface-ring" />
              <circle r="4" className="brand-surface-core" />
              <text x="20" y="4" className="brand-surface-label">{n.id}</text>
            </g>
          ),
        )}
      </g>
    </svg>
  );
}

const q = (root: HTMLElement, selector: string) => Array.from(root.querySelectorAll<Element>(selector));

/** The form arrives FIRST and fast (the person came to sign in); the picture keeps arriving behind it. */
function entrance(root: HTMLElement): gsap.core.Timeline {
  return gsap
    .timeline({ defaults: { ease: "expo.out" } })
    .from(q(root, ".brand-surface-panel-in > *"), { autoAlpha: 0, y: 14, duration: 0.6, stagger: 0.06 }, 0.1)
    .from(q(root, ".brand-surface-brand > *"), { autoAlpha: 0, y: 18, duration: 0.9, stagger: 0.1 }, 0.2)
    .from(q(root, ".brand-surface-grid"), { autoAlpha: 0, duration: 1.2, ease: "power1.out" }, 0)
    .from(q(root, ".brand-surface-route"), {
      strokeDashoffset: (_: number, el: Element) => Number(el.getAttribute("data-length")),
      duration: 1.1,
      stagger: 0.035,
      ease: "power3.inOut",
    }, 0.1)
    .from(q(root, ".brand-surface-node"), { autoAlpha: 0, scale: 0.5, transformOrigin: "50% 50%", duration: 0.7, stagger: { each: 0.04, from: "random" } }, 0.35)
    .from(q(root, ".brand-surface-label"), { autoAlpha: 0, duration: 0.6, stagger: 0.02, ease: "power1.out" }, 0.9);
}

/** What keeps moving once the screen has arrived: work running along the routes. Pausable. */
function ambient(root: HTMLElement): gsap.core.Timeline {
  const tl = gsap.timeline({ repeat: -1, paused: true });
  q(root, ".brand-surface-packet").forEach((packet, i) => {
    const length = Number(packet.getAttribute("data-length"));
    tl.fromTo(packet, { strokeDashoffset: 18 }, { strokeDashoffset: -length, duration: length / 170, ease: "none" }, ((i * 7) % 19) * 0.55);
  });
  tl.to(q(root, ".brand-surface-actor .brand-surface-core"), { scale: 1.6, transformOrigin: "50% 50%", duration: 0.5, yoyo: true, repeat: 1, stagger: 1.4, ease: "sine.inOut" }, 0.4);
  return tl;
}

export interface BrandSurfaceProps {
  /** The product's identity: its own `<Logo … wordmark={…} />`, or the tenant's uploaded logo and name. Never redrawn here. */
  brand: ReactNode;
  /** ONE plain value line, already translated. */
  valueLine: ReactNode;
  /** Optional fact line (what the product connects), set in mono. */
  facts?: ReactNode;
  /** The page's one h1: "Sign in", "Reset password", … */
  title: string;
  error?: string;
  pauseLabel: string;
  playLabel: string;
  /** false when the page speaks a language the server chose. */
  localePicker?: boolean;
  /** The form: Form + FormField + Input / PasswordInput + Button, exactly as on a plain auth page. */
  children: ReactNode;
}

export function BrandSurface({ brand, valueLine, facts, title, error, pauseLabel, playLabel, localePicker = true, children }: BrandSurfaceProps) {
  const root = useRef<HTMLElement>(null);
  const loop = useRef<gsap.core.Timeline | null>(null);
  const [still, setStill] = useState(false);
  const stillRef = useRef(false);

  useGSAP(
    () => {
      const element = root.current;
      if (!element) return;
      const mm = gsap.matchMedia();
      mm.add({ full: "(prefers-reduced-motion: no-preference)", reduced: "(prefers-reduced-motion: reduce)" }, (context) => {
        if (context.conditions?.reduced) {
          // At rest: the picture is drawn, the form fades in, nothing loops.
          gsap.from(q(element, ".brand-surface-panel-in"), { autoAlpha: 0, duration: 0.3, ease: "power1.out" });
          loop.current = null;
          return;
        }
        loop.current = ambient(element);
        entrance(element).eventCallback("onComplete", () => {
          if (!stillRef.current) loop.current?.play();
        });
      });
      return () => mm.revert();
    },
    { scope: root },
  );

  function toggleMotion() {
    const next = !still;
    stillRef.current = next;
    setStill(next);
    if (next) loop.current?.pause();
    else loop.current?.play();
  }

  return (
    // ThemeScope carries the surface's re-set tokens into the overlays it opens (the locale menu).
    <ThemeScope className="brand-surface">
      <main ref={root} className="brand-surface-main">
        <div className="brand-surface-stage">
          <ProductMap />
        </div>
        <header className="brand-surface-brand">
          {brand}
          <Text as="p" className="brand-surface-value" break="phrase">{valueLine}</Text>
          {facts ? <Text as="p" mono className="brand-surface-facts">{facts}</Text> : null}
        </header>
        <section className="brand-surface-panel" aria-labelledby="brand-surface-title">
          <div className="brand-surface-panel-in">
            <Heading level={1} id="brand-surface-title" className="brand-surface-title">{title}</Heading>
            {error ? <Alert tone="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}
            <div>{children}</div>
            <Flex align="center" justify="between" gap="sm">
              {localePicker ? <AppSettingPicker kind="locale" appearance="labeled" compact /> : <span />}
              <AppSettingPicker kind="theme" menu={false} appearance="icon" />
            </Flex>
          </div>
        </section>
        {/* Beside the picture it stops, last in the tab order (WCAG 2.2.2). Hidden by the CSS under reduced motion. */}
        <Button type="button" variant="ghost" size="icon" className="brand-surface-motion" onClick={toggleMotion} aria-label={still ? playLabel : pauseLabel}>
          {still ? <Play aria-hidden /> : <Pause aria-hidden />}
        </Button>
      </main>
    </ThemeScope>
  );
}

